// ASCII 可打印字符
const ASCII = ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~'

// 标点符号
const PUNCTUATION = '，。、；：？！「」『』【】（）《》—…·〈〉""'

// 合并所有字符并去重
function getCharset() {
  const allChars = COMMON_CHINESE + MEDICAL_CHARS + ASCII + PUNCTUATION
  return [...new Set(allChars.split(''))].join('')
}

async function main() {
  // 源字体路径（从后端项目）
  const sourceFontPath = join(__dirname, '../../backend/public/fonts/SourceHanSerifSC-Regular.otf')
  
  if (!existsSync(sourceFontPath)) {
    console.error('❌ 源字体文件不存在:', sourceFontPath)
    console.log('请确保 public/fonts/SourceHanSerifSC-Regular.otf 存在')
    process.exit(1)
  }

  console.log('📖 读取源字体文件...')
  const fontBuffer = readFileSync(sourceFontPath)
  
  const charset = getCharset()
  console.log(`📝 字符集大小: ${charset.length} 字符`)

  console.log('✂️ 子集化字体...')
  const subsetBuffer = await subsetFont(fontBuffer, charset, {
    targetFormat: 'woff2'
  })

  // 输出路径
  const outputPath = join(__dirname, '../src/fonts/SourceHanSerifSC-Regular-subset.woff2')
  writeFileSync(outputPath, subsetBuffer)
  
  const originalSize = (fontBuffer.length / 1024 / 1024).toFixed(2)
  const subsetSize = (subsetBuffer.length / 1024 / 1024).toFixed(2)
  const reduction = ((1 - subsetBuffer.length / fontBuffer.length) * 100).toFixed(1)
  
  console.log(`✅ 子集化完成!`)
  console.log(`   原始大小: ${originalSize} MB`)
  console.log(`   子集大小: ${subsetSize} MB`)
  console.log(`   压缩率: ${reduction}%`)
  console.log(`   输出: ${outputPath}`)

  // 生成 Base64 数据文件
  console.log('📦 生成 Base64 数据文件...')
  const base64Data = subsetBuffer.toString('base64')
  const dataUrl = `data:font/woff2;base64,${base64Data}`
  
  const fontDataPath = join(__dirname, '../src/fonts/font-data.ts')
  const fontDataContent = `/**
 * @fileoverview Source Han Serif SC Regular font data (subset)
 * @module fonts/font-data
 * @description Contains subset font with common CJK characters + ASCII + medical-specific characters
 * 
 * Generation command: node scripts/subset-font.mjs
 * Source font: Source Han Serif SC Regular
 * Character set size: ${charset.length} characters
 * File size: ${subsetSize} MB
 */

/** Font Data URL (woff2 format, Base64 encoded) */
export const FONT_DATA_URL = '${dataUrl}'

/** Font family name */
export const FONT_FAMILY = 'Source Han Serif SC'

/** Font weight */
export const FONT_WEIGHT = 400

/** Font style */
export const FONT_STYLE = 'normal'
`
  
  writeFileSync(fontDataPath, fontDataContent)
  console.log(`✅ Base64 数据文件已生成: ${fontDataPath}`)
}

main().catch(console.error)
